// This code node extracts metadata (title, description, tags, hashtags, etc.) from an input string
// that is expected to contain a JSON object.

// Get the raw text input from the first item in the input data.
const rawInputString = $input.first().json.text;

/**
 * Attempts to extract and "fix" a valid JSON string from potentially malformed or
 * truncated input, especially common LLM output issues like missing closing
 * quotes or braces at the very end.
 * WARNING: This is a highly speculative and brittle approach. The best solution
 * is always to ensure valid JSON generation upstream via responseSchema.
 * @param {string} str The input string.
 * @returns {string} The cleaned string, ideally a valid JSON.
 */
function extractValidJsonAggressive(str) {
  let cleanedStr = str.trim();

  // Find the first opening curly brace and the last closing curly brace
  const firstBrace = cleanedStr.indexOf('{');
  let lastBrace = cleanedStr.lastIndexOf('}');

  if (firstBrace === -1) {
    // No opening brace found, cannot parse as JSON object
    return cleanedStr;
  }

  // If there's an opening brace but no closing brace, or closing brace is before opening
  if (lastBrace === -1 || lastBrace < firstBrace) {
    // Assume truncation and try to append missing characters
    cleanedStr = cleanedStr.substring(firstBrace); // Start from the first brace

    // Aggressive attempts to close common truncation errors at the end
    // (e.g., if the LLM stopped mid-field or before the final brace)
    if (!cleanedStr.endsWith('"') && cleanedStr.includes(':')) { // Heuristic: if it looks like a key-value pair and missing closing quote
      cleanedStr += '"';
    }
    if (!cleanedStr.endsWith('}')) {
      cleanedStr += '}'; // Assume missing closing brace
    }
    // Re-check for trailing comma before the *newly added* closing brace
    if (cleanedStr.endsWith(',}')) {
      cleanedStr = cleanedStr.substring(0, cleanedStr.length - 2) + '}';
    }

    // Attempt to parse this "fixed" string to get an actual lastBrace if it was missing
    try {
      JSON.parse(cleanedStr);
      lastBrace = cleanedStr.lastIndexOf('}'); // Update lastBrace if successful
    } catch (e) {
      // Still invalid, proceed with the string as is for now.
    }
  }

  // Re-extract based on potentially fixed braces, or original if no fix applied
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace >= firstBrace) {
    cleanedStr = cleanedStr.substring(firstBrace, lastBrace + 1);
    // Final check for trailing comma before the absolute last brace
    if (cleanedStr.endsWith(',}')) {
      cleanedStr = cleanedStr.substring(0, cleanedStr.length - 2) + '}';
    }
  }


  // Final check to see if it's parseable after aggressive attempts
  try {
    JSON.parse(cleanedStr);
    return cleanedStr;
  } catch (e) {
    // Even after aggressive fixing, it's not valid JSON.
    // Log the error and the problematic string for debugging upstream.
    console.warn("Aggressive JSON fix failed:", e.message, "Attempted JSON:", cleanedStr);
    return str; // Fallback to original, let JSON.parse in main block fail
  }
}

let parsedData;
let outputTitle = '';
let outputDescription = '';
let outputTags = '';
let outputHashtags = ''; // New variable for hashtags
let outputTopText = '';
let outputBottomText = '';

try {
  // Use the aggressive extraction function
  const cleanedJsonString = extractValidJsonAggressive(rawInputString);

  // Attempt to parse the cleaned string. If it's still malformed, this will throw an error.
  parsedData = JSON.parse(cleanedJsonString);

  // Check if the parsed result is a valid object.
  if (typeof parsedData === 'object' && parsedData !== null) {
    // Assign values, defaulting to empty string if a property is missing.
    outputTitle = parsedData.title || '';
    outputDescription = parsedData.description || '';

    // Tags might be an array or string; handle both if possible, or force string.
    if (Array.isArray(parsedData.tags)) {
      outputTags = parsedData.tags.join(','); // Join array elements with commas
    } else {
      outputTags = parsedData.tags || '';
    }

    // Handle hashtags, assuming it's a string, or array if AI might generate it as such.
    if (Array.isArray(parsedData.hashtags)) {
      // Join array elements with spaces, and ensure each hashtag starts with '#'
      outputHashtags = parsedData.hashtags.map(tag => tag.startsWith('#') ? tag : '#' + tag).join(' ');
    } else if (typeof parsedData.hashtags === 'string') {
      // If it's a string, ensure all space-separated words are prefixed with #
      outputHashtags = parsedData.hashtags.split(' ').map(tag => tag.startsWith('#') ? tag : '#' + tag).join(' ');
    } else {
      outputHashtags = '';
    }

    outputTopText = parsedData.top_text || '';
    outputBottomText = parsedData.bottom_text || '';
  } else {
    // If parsing succeeded but result is not an object (e.g., just "null" or "true"),
    // treat it as an error to ensure structured output.
    throw new Error('Parsed JSON is not a valid object');
  }
} catch (e) {
  // If any error occurs during parsing or extraction,
  // we default to putting the raw input into the description
  // and logging the error to help debugging upstream.
  console.error("JSON parsing error (main block):", e.message);
  outputDescription = rawInputString; // Fallback: put raw input into description
}

// Return the structured output.
return [{
  json: {
    output: {
      title: outputTitle,
      description: outputDescription,
      tags: outputTags,
      hashtags: outputHashtags, // Include hashtags in the output
      top_text: outputTopText,
      bottom_text: outputBottomText
    }
  }
}];
